def resolve(path, cwd, links):
    if not isinstance(path, str) or not isinstance(cwd, str) or not isinstance(links, dict):
        return None

    # Start with cwd if path is relative
    if path.startswith('/'):
        current = '/'
        remaining = path[1:]
    else:
        current = cwd
        remaining = path

    # Track symlinks followed to prevent infinite loops
    links_followed = 0
    max_links = 8

    while True:
        # Split remaining path into components
        components = remaining.split('/')

        for component in components:
            # Skip empty components and '.'
            if component == '' or component == '.':
                continue

            # Handle '..'
            if component == '..':
                # Move to parent directory
                if current != '/':
                    current = current.rsplit('/', 1)[0]
                    if not current:
                        current = '/'
                continue

            # Append component to current path
            if current == '/':
                current = '/' + component
            else:
                current = current + '/' + component

            # Check if current path is a symlink
            if current in links:
                # We've hit a symlink
                links_followed += 1
                if links_followed > max_links:
                    return None

                target = links[current]

                # Determine the remaining components we haven't processed yet
                # We need to find where we are in the components list
                component_index = components.index(component)
                remaining_components = components[component_index + 1:]

                # If target is absolute, start from root; otherwise, resolve relative to link's directory
                if target.startswith('/'):
                    current = '/'
                    remaining = target[1:]
                else:
                    # Target is relative to the directory containing the link
                    current = current.rsplit('/', 1)[0]
                    if not current:
                        current = '/'
                    remaining = target

                # Append remaining components
                if remaining_components:
                    if remaining:
                        remaining = remaining + '/' + '/'.join(remaining_components)
                    else:
                        remaining = '/'.join(remaining_components)

                # Break inner loop to restart with new remaining path
                break
        else:
            # No symlink was encountered in this batch of components
            break

    # Return the result without trailing slash (except for '/')
    if current == '/':
        return '/'
    else:
        return current

